// Post-preflight analysis, frozen before the new isolated/interleaved data.
mod antecedent {
    include!("audit.rs");
    pub fn replay(c:&std::path::Path,a:&std::path::Path,b:&std::path::Path)->serde_json::Value{audit(c,a,b)}
}
use std::{fs,path::Path,io::Write};use serde_json::{Value,json};
fn interval(xs:&[f64])->(f64,f64,f64,f64){assert_eq!(xs.len(),5);let mean=xs.iter().sum::<f64>()/5.;let variance=xs.iter().map(|x|(x-mean)*(x-mean)).sum::<f64>()/4.;let se=(variance/5.).sqrt();let delta=2.7764451051977987*se;let t=if se==0.{if mean==0.{0.}else{f64::INFINITY}}else{mean.abs()/se};let u=if t.is_infinite(){1.}else{t/(t*t+4.).sqrt()};let p=(1.-1.5*u+0.5*u*u*u).clamp(0.,1.);((mean-delta).exp(),(mean+delta).exp(),mean,p)}
fn log_ratios(x:&Value,y:&Value)->Vec<f64>{let a=x["timings"].as_array().unwrap();let b=y["timings"].as_array().unwrap();assert_eq!(a.len(),6);assert_eq!(b.len(),6);(1..6).map(|i|{let u=a[i]["cold_ns"].as_u64().unwrap();let v=b[i]["cold_ns"].as_u64().unwrap();assert!(u>0&&v>0);(u as f64/v as f64).ln()}).collect()}
fn main(){let args:Vec<_>=std::env::args().collect();if args.len()!=5{std::process::exit(2)}let result=std::panic::catch_unwind(||{
let mut receipt=antecedent::replay(Path::new(&args[1]),Path::new(&args[2]),Path::new(&args[3]));let a:Value=serde_json::from_slice(&fs::read(Path::new(&args[2]).join("index.json")).unwrap()).unwrap();let b:Value=serde_json::from_slice(&fs::read(Path::new(&args[3]).join("index.json")).unwrap()).unwrap();let mut paired=vec![];let mut aa=vec![];
for(tag,data)in[("A",&a),("B",&b)]{for(from,to)in[(0,1),(1,2),(2,3),(0,3)]{for policy in 0..455{for offset in 0..2{let cap=offset+3;let x=&data["cases"][from*910+policy*2+offset]["summary"]["works"];let y=&data["cases"][to*910+policy*2+offset]["summary"]["works"];for target in 0..30{if x[target]["result"]["kind"]!=1||y[target]["result"]["kind"]!=1{continue}let xs=log_ratios(&x[target],&y[target]);let(lo,hi,mean,p)=interval(&xs);paired.push(json!({"stream":tag,"from":from,"to":to,"policy":policy,"cap":cap,"target":target+1,"geometric_mean_ratio":mean.exp(),"paired_log_t4_95_interval":[lo,hi],"two_sided_p":p,"holm_rejected":false,"candidate_faster":mean>0.}));}}}}}
let mut order:Vec<usize>=(0..paired.len()).collect();order.sort_by(|&i,&j|paired[i]["two_sided_p"].as_f64().unwrap().total_cmp(&paired[j]["two_sided_p"].as_f64().unwrap()));for(rank,&i)in order.iter().enumerate(){let threshold=0.05/(order.len()-rank)as f64;if paired[i]["two_sided_p"].as_f64().unwrap()>threshold{break}paired[i]["holm_rejected"]=json!(true);}
for route in 0..4{for policy in 0..455{for offset in 0..2{let x=&a["cases"][route*910+policy*2+offset]["summary"]["works"];let y=&b["cases"][route*910+policy*2+offset]["summary"]["works"];for target in 0..30{let xs=log_ratios(&x[target],&y[target]);let(lo,hi,mean,p)=interval(&xs);aa.push(json!({"route":route,"policy":policy,"cap":offset+3,"target":target+1,"A_over_B_geometric_ratio":mean.exp(),"paired_log_t4_95_interval":[lo,hi],"two_sided_p":p}));}}}}
let mut summary=vec![];for tag in["A","B"]{for(from,to)in[(0,1),(1,2),(2,3),(0,3)]{for cap in[3,4]{let rows:Vec<_>=paired.iter().filter(|v|v["stream"]==tag&&v["from"]==from&&v["to"]==to&&v["cap"]==cap).collect();let unadjusted=rows.iter().filter(|v|v["paired_log_t4_95_interval"][0].as_f64().unwrap()>1.).count();let holm=rows.iter().filter(|v|v["holm_rejected"]==true&&v["candidate_faster"]==true).count();summary.push(json!({"stream":tag,"from":from,"to":to,"cap":cap,"eligible":rows.len(),"unadjusted95_faster":unadjusted,"holm_faster":holm}));}}}
receipt["paired_summary"]=json!(summary);receipt["paired_intervals"]=json!(paired);receipt["AA_intervals"]=json!(aa);receipt["interval_assumptions"]=json!("Five paired interleaved rounds; two-sided Student-t4 intervals for independent normal log-time differences; Holm across all eligible pairs in both streams; host isolation separate official receipt, not inferred. Tiny fixtures and shared-host noise limit interpretation.");fs::OpenOptions::new().write(true).create_new(true).open(&args[4]).unwrap().write_all((serde_json::to_string(&receipt).unwrap()+"\n").as_bytes()).unwrap();});if result.is_err(){std::process::exit(101)}}
